'use strict';
/* Pour Lab: All user-entered data remains in this browser's local IndexedDB.
   No analytics, accounts, third-party scripts or telemetry. */
const STORAGE_KEY='pourlab-data-v1';
const STORE_NAME='documents';
const DOC_KEY='notebook';
const VERSION=1;
const uid=()=>`${Date.now().toString(36)}-${Math.random().toString(36).slice(2,10)}`;
const $=(id)=>document.getElementById(id);
const html=(value)=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const n=(value,fallback=0)=>Number.isFinite(Number(value))&&value!==''?Number(value):fallback;
const clamp=(value,min,max)=>Math.min(max,Math.max(min,value));
const fmt=(secs)=>{const s=Math.max(0,Math.floor(Number(secs)||0));return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;};
const parseTime=(str)=>{str=String(str||'').trim();if(!str)return NaN;if(/^\d+:\d{1,2}$/.test(str)){let [m,s]=str.split(':').map(Number);return s<60?m*60+s:NaN;}return /^\d+$/.test(str)?Number(str):NaN;};
const formatDate=(s)=>new Date(s).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});
const shortDate=(s)=>new Date(s).toLocaleDateString(undefined,{month:'short',day:'numeric'});
const round=(num,d=1)=>Number(num).toFixed(d).replace(/\.0+$/,'');
const ratio=r=>r.dose>0?round(r.water/r.dose,1):'—';
const grindText=r=>`${round(r.grindRot,0)} rotations + ${round(r.grindDial,1)} on dial`;
const TODAY='2026-10-29'; // reference knowledge-pack version; not used for actual brew dates

