function defaultState(){
 const beanId=uid();const aId=uid(),bId=uid();
 const current=new Date().toISOString();
 return {version:VERSION,beans:[{id:beanId,name:'Colombia · Melon-washed',origin:'Colombia',region:'',variety:'Arabica',process:'Melon-washed (roaster label)',roast:'Medium',roaster:'',notes:'Producer/roaster term; processing details not yet confirmed.',createdAt:current}],recipes:[
 {id:aId,beanId,name:'Sweet & fruity · Four pours',dose:15,water:225,temp:92,grindRot:3,grindDial:4.5,targetTime:165,mode:'manual',pours:[{at:0,water:45},{at:40,water:120},{at:75,water:180},{at:110,water:225}],notes:'Experimental starting schedule. Let taste and bed behavior guide changes.',createdAt:current,updatedAt:current},
 {id:bId,beanId,name:'Sweet & fruity · Three pours',dose:15,water:225,temp:92,grindRot:3,grindDial:4.5,targetTime:165,mode:'manual',pours:[{at:0,water:45},{at:40,water:180},{at:90,water:225}],notes:'Experimental alternative with fewer pours. Compare side by side.',createdAt:current,updatedAt:current}
 ],brews:[],settings:{sound:true,keepAwake:true,selectedRecipeId:aId}};
}
let state,db=null,storageMode='indexedDB';
const ui={tab:'brew',recipeTab:'recipes',learnTab:'guide',selectedRecipeId:null,historyBeanId:'all',compareA:'',compareB:'',origin:'Colombia',process:'Washed',roast:'Medium',runner:null,timerHandle:null,toastHandle:null,audio:null};
async function openDatabase(){return new Promise((resolve,reject)=>{
 const req=indexedDB.open('pourlab-offline',1);
 req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains(STORE_NAME))req.result.createObjectStore(STORE_NAME);};
 req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);
 });}
async function readState(){try{db=await openDatabase();const data=await new Promise((res,rej)=>{const tx=db.transaction(STORE_NAME,'readonly');const req=tx.objectStore(STORE_NAME).get(DOC_KEY);req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error);});if(data)return data;}catch(e){storageMode='localStorage';console.warn('IndexedDB unavailable',e);}try{const raw=localStorage.getItem(STORAGE_KEY);if(raw)return JSON.parse(raw);}catch(e){console.warn('LocalStorage unavailable',e);}return null;}
async function save(){state.version=VERSION;try{if(db){await new Promise((resolve,reject)=>{const tx=db.transaction(STORE_NAME,'readwrite');tx.objectStore(STORE_NAME).put(state,DOC_KEY);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}else localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch(e){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageMode='localStorage';}catch(err){toast('Storage is unavailable. Export a backup now.');console.error(err);}}}
async function persistAndRender(message){await save();render();if(message)toast(message);}
function getRecipe(id){return state.recipes.find(r=>r.id===id);}
function getBean(id){return state.beans.find(b=>b.id===id);}
function selectedRecipe(){return getRecipe(ui.selectedRecipeId)||state.recipes[0];}
function recipeName(r){return getBean(r.beanId)?.name||'Unknown bean';}
function stageLabel(i){return i===0?'Bloom':`Pour ${i+1}`;}
function toast(msg){const node=$('toast');node.textContent=msg;node.classList.add('show');clearTimeout(ui.toastHandle);ui.toastHandle=setTimeout(()=>node.classList.remove('show'),2900);}
function setTab(tab){ui.tab=tab;render();window.scrollTo({top:0,behavior:'instant'});}
function render(){document.querySelectorAll('[data-nav]').forEach(x=>x.classList.toggle('selected',x.dataset.nav===ui.tab));$('connection-status').innerHTML='<span class="status-dot"></span> Local only';let body;
 switch(ui.tab){case 'brew':body=renderHome();break;case 'recipes':body=renderRecipes();break;case 'history':body=renderHistory();break;case 'learn':body=renderLearn();break;case 'settings':body=renderSettings();break;default:body=renderHome();}
 $('main').innerHTML=`<div class="page">${body}</div>`;
}
function header(kicker,title,sub){return `<p class="eyebrow">${kicker}</p><h1 class="page-title">${title}</h1><p class="page-sub">${sub}</p>`;}
function metric(value,label){return `<div class="metric"><div class="metric-value">${html(value)}</div><div class="metric-label">${html(label)}</div></div>`;}
function recipeMetrics(r){return `<div class="metric-grid">${metric(`${r.dose} g`,'Coffee dose')}${metric(`${r.water} g`,`Water / 1:${ratio(r)}`)}${metric(`${r.temp}°C`,'Water temp')}${metric(fmt(r.targetTime),'Target finish')}${metric(`${r.grindRot}r · ${r.grindDial}`,'X-Ultra setting')}${metric(r.pours.length,'Pour stages')}</div>`;}
function pourDiagram(r){return `<div class="pours">${r.pours.map((p,i)=>`<div><div class="pour-row"><span class="pour-time">${fmt(p.at)}</span><div class="pour-track"><div class="pour-bar" style="width:${100*p.water/r.water}%"></div></div><span class="pour-target">${p.water} g</span></div><div class="pour-description">${stageLabel(i)} · add ${round(p.water-(r.pours[i-1]?.water||0),1)} g</div></div>`).join('')}</div>`;}
function renderHome(){const r=selectedRecipe();const latest=[...state.brews].sort((a,b)=>new Date(b.date)-new Date(a.date)).slice(0,2);return `${header('BREWING WORKSPACE','Make something good.','Your V60 NEO 02 setup, measured pours and sensory notes in one private notebook.')}
 <div class="card active-card"><div class="card-kicker">YOUR NEXT BREW</div><label class="field-label" for="home-recipe">Choose a recipe</label><select id="home-recipe" class="select" data-change="select-recipe">${state.recipes.map(x=>`<option value="${x.id}" ${x.id===r?.id?'selected':''}>${html(x.name)} — ${html(recipeName(x))}</option>`).join('')}</select>
 ${r?`<h2 class="card-title" style="margin-top:16px">${html(recipeName(r))}</h2><div class="chip-row"><span class="chip">${html(getBean(r.beanId)?.roast||'Unknown roast')}</span><span class="chip gold">X-Ultra ${r.grindRot}r + ${r.grindDial}</span><span class="chip blue">${r.mode==='manual'?'Bed-visible pacing':'Scheduled cues'}</span></div>${recipeMetrics(r)}<div class="rule"></div>${pourDiagram(r)}<div class="section-separator"></div><div class="actions"><button class="btn" data-act="start-brew">Start guided brew →</button><button class="btn secondary" data-act="edit-recipe" data-id="${r.id}">Edit</button></div>`:'<p>No recipes yet.</p>'}</div>
 <div class="notice blue"><b>Starting point, not a fixed rule.</b> Your 3 rotations + 4.5 X-Ultra setting and 92°C starting water are editable. Compare actual taste rather than forcing a drawdown time.</div>
 <div class="section-header"><h2 class="section-title">Your brew log</h2><button class="button-link" data-nav-to="history">View all →</button></div>
 ${latest.length?latest.map(b=>brewHistoryCard(b,true)).join(''):'<div class="empty"><b>Your first tasting is next.</b><div>Complete a guided brew to begin tracking sweetness, acidity, body and clarity.</div></div>'}
 <div class="section-header"><h2 class="section-title">Evidence-led dial-in</h2><button class="button-link" data-nav-to="learn">Open library →</button></div><div class="card compact"><p class="muted-sm" style="margin:0">The source library separates peer-reviewed findings from experimental recipes. Origin alone cannot determine the best grind, temperature or pour schedule.</p></div>`;}
function recipeCard(r){const b=getBean(r.beanId);return `<div class="card compact"><div class="list-card"><div class="grow"><div class="card-kicker">${html(b?.origin||'Unspecified origin')} · ${html(b?.process||'Unknown process')}</div><h3 style="margin-top:6px">${html(r.name)}</h3><p>${html(b?.name||'Unknown bean')} · ${r.dose}g / ${r.water}g · ${r.temp}°C · ${r.grindRot}r + ${r.grindDial}</p><p style="margin-top:5px">${r.pours.length} pours · ${fmt(r.targetTime)} target · ${r.mode==='manual'?'Bed-visible':'Scheduled'}</p></div><div class="list-actions"><button class="icon-button" aria-label="Edit ${html(r.name)}" data-act="edit-recipe" data-id="${r.id}">✎</button></div></div><div class="actions margin-top"><button class="btn small" data-act="use-recipe" data-id="${r.id}">Use recipe</button><button class="btn secondary small" data-act="duplicate-recipe" data-id="${r.id}">Duplicate</button><button class="btn ghost small" data-act="delete-recipe" data-id="${r.id}">Delete</button></div></div>`;}
function beanCard(b){const count=state.recipes.filter(r=>r.beanId===b.id).length;return `<div class="card compact"><div class="list-card"><div class="grow"><h3>${html(b.name)}</h3><p>${html(b.origin||'Origin unknown')} · ${html(b.variety||'Variety unspecified')} · ${html(b.roast)} · ${html(b.process)}</p>${b.roaster?`<p>Roaster: ${html(b.roaster)}</p>`:''}${b.notes?`<p>${html(b.notes)}</p>`:''}<div class="chip-row"><span class="chip gray">${count} ${count===1?'recipe':'recipes'}</span></div></div><button class="icon-button" aria-label="Edit bean" data-act="edit-bean" data-id="${b.id}">✎</button></div><div class="actions"><button class="btn secondary small" data-act="create-recipe-for-bean" data-id="${b.id}">+ Recipe</button><button class="btn ghost small" data-act="delete-bean" data-id="${b.id}">Delete</button></div></div>`;}
function renderRecipes(){return `${header('PERSONAL LIBRARY','Recipes & beans.','Build your own repeatable reference for every coffee you try.')}
 <div class="segment" style="margin-bottom:14px"><button class="${ui.recipeTab==='recipes'?'on':''}" data-act="switch-recipe-tab" data-value="recipes">Recipes (${state.recipes.length})</button><button class="${ui.recipeTab==='beans'?'on':''}" data-act="switch-recipe-tab" data-value="beans">Coffee beans (${state.beans.length})</button></div>
 <div class="actions" style="margin-bottom:14px"><button class="btn" data-act="${ui.recipeTab==='beans'?'add-bean':'add-recipe'}">+ ${ui.recipeTab==='beans'?'New coffee bean':'New recipe'}</button></div>
 ${ui.recipeTab==='recipes'?(state.recipes.map(recipeCard).join('')||'<div class="empty">No recipes. Add your first recipe.</div>'):(state.beans.map(beanCard).join('')||'<div class="empty">No coffee beans saved.</div>')}`;}
function brewHistoryCard(b,short=false){const r=b.recipeSnapshot||getRecipe(b.recipeId)||{};const bean=getBean(b.beanId);const title=b.beanName||bean?.name||'Unknown bean';return `<div class="card compact"><div class="flex between"><span class="card-kicker">${formatDate(b.date)}</span><span class="score">${b.rating?b.rating+'/10':'—'}</span></div><h3 style="font-size:15px;margin:4px 0">${html(title)}</h3><div class="muted-sm">${html(r.name||'Saved brew')} · ${fmt(b.actualTime)} · ${r.temp||'—'}°C · ${r.dose||'—'}g/${r.water||'—'}g</div>${b.notes?`<p class="muted-sm">${html(b.notes)}</p>`:''}<div class="actions margin-top"><button class="btn secondary small" data-act="view-brew" data-id="${b.id}">Details ${short?'':'/ edit'}</button><button class="btn ghost small" data-act="repeat-brew" data-id="${b.id}">Repeat setup</button></div></div>`;}
function renderHistory(){const brews=[...state.brews].filter(b=>ui.historyBeanId==='all'||b.beanId===ui.historyBeanId).sort((a,b)=>new Date(b.date)-new Date(a.date));const ids=brews.map(b=>b.id);if(!ids.includes(ui.compareA))ui.compareA=ids[0]||'';if(!ids.includes(ui.compareB))ui.compareB=ids[1]||'';const opts=(val)=>`<option value="">Choose a brew</option>${brews.map(b=>`<option value="${b.id}" ${b.id===val?'selected':''}>${shortDate(b.date)} · ${html(b.beanName||getBean(b.beanId)?.name||'Coffee')} · ${b.rating||'—'}/10</option>`).join('')}`;return `${header('TASTING NOTEBOOK','Your brew journal.','Compare actual results to find the method that makes your beans shine.')}
 <div class="metric-grid">${metric(state.brews.length,'Brew sessions')}${metric(state.brews.length?round(state.brews.reduce((s,x)=>s+(x.rating||0),0)/state.brews.filter(x=>x.rating>0).length||0,1):'—','Average / 10')}${metric(new Set(state.brews.map(x=>x.beanId)).size,'Coffee beans tried')}</div>
 <div class="card"><div class="section-title">Compare two brews</div><div class="form-grid"><div><label class="field-label">Brew A</label><select class="select" data-change="compare-a">${opts(ui.compareA)}</select></div><div><label class="field-label">Brew B</label><select class="select" data-change="compare-b">${opts(ui.compareB)}</select></div></div>${renderComparison()}</div>
 <div class="section-header"><h2 class="section-title">Sessions</h2><span class="section-kicker">${brews.length} entries</span></div><label class="field-label" for="filter-history">Filter by bean</label><select id="filter-history" class="select" data-change="filter-history" style="margin-bottom:12px"><option value="all">All coffee beans</option>${state.beans.map(b=>`<option value="${b.id}" ${ui.historyBeanId===b.id?'selected':''}>${html(b.name)}</option>`).join('')}</select>
 ${brews.length?brews.map(b=>brewHistoryCard(b)).join(''):'<div class="empty"><b>No logged brews yet.</b><div>Start a guided brew, then enter your impressions to build comparison data.</div></div>'}`;}
function renderComparison(){const a=state.brews.find(b=>b.id===ui.compareA),b=state.brews.find(b=>b.id===ui.compareB);if(!a||!b||a.id===b.id)return '<p class="muted-sm">Select two different sessions to compare their brewing parameters and tasting ratings.</p>';const ar=a.recipeSnapshot||{},br=b.recipeSnapshot||{};const rows=[['Rating',a.rating?a.rating+'/10':'—',b.rating?b.rating+'/10':'—'],['Brew time',fmt(a.actualTime),fmt(b.actualTime)],['Coffee',`${ar.dose} g`,`${br.dose} g`],['Water',`${ar.water} g`,`${br.water} g`],['Ratio',`1:${ratio(ar)}`,`1:${ratio(br)}`],['Temperature',`${ar.temp}°C`,`${br.temp}°C`],['Grind',`${ar.grindRot}r + ${ar.grindDial}`,`${br.grindRot}r + ${br.grindDial}`],['Pours',ar.pours?.length||0,br.pours?.length||0],['Sweetness',a.senses?.sweetness??'—',b.senses?.sweetness??'—'],['Acidity',a.senses?.acidity??'—',b.senses?.acidity??'—'],['Body',a.senses?.body??'—',b.senses?.body??'—'],['Clarity',a.senses?.clarity??'—',b.senses?.clarity??'—']];return `<table class="data-table" aria-label="Brew comparison"><thead><tr><th>Measure</th><th>A</th><th>B</th></tr></thead><tbody>${rows.map(([label,v1,v2])=>`<tr><td>${label}</td><td>${html(v1)}</td><td>${html(v2)}</td></tr>`).join('')}</tbody></table><p class="field-help">Ratings are personal sensory records. A difference in score does not isolate a cause if several variables changed.</p>`;}
function renderLearn(){const o=ORIGINS.find(x=>x.name===ui.origin)||ORIGINS[0];return `${header('OFFLINE REFERENCE','Brew knowledge.','Research summaries remain on your phone after the app has been installed and opened online once.')}
 <div class="segment" style="margin-bottom:16px"><button class="${ui.learnTab==='guide'?'on':''}" data-act="switch-learn-tab" data-value="guide">Origin & process</button><button class="${ui.learnTab==='trouble'?'on':''}" data-act="switch-learn-tab" data-value="trouble">Troubleshoot</button><button class="${ui.learnTab==='research'?'on':''}" data-act="switch-learn-tab" data-value="research">Research</button></div>
 ${ui.learnTab==='research'?renderResearch():ui.learnTab==='trouble'?renderTroubleshoot():renderGuide(o)}`;}
function renderGuide(origin){const temp=ui.roast==='Light'?94:ui.roast==='Dark'?89:92;const cp=PROCESSES.find(p=>p.name===ui.process);return `<div class="notice blue"><b>Research boundary:</b> There is no validated universal V60 recipe for a country. These are illustrative origin notes plus a transparent <b>experimental starting point</b>. Processing, roast, freshness and your taste take priority.</div>
 <div class="card" style="margin-top:13px"><div class="card-kicker">EXPLORE A COFFEE</div><div class="form-grid"><div><label class="field-label">Country of origin</label><select class="select" data-change="guide-origin">${ORIGINS.map(o=>`<option ${ui.origin===o.name?'selected':''}>${html(o.name)}</option>`).join('')}</select></div><div><label class="field-label">Roast level</label><select class="select" data-change="guide-roast">${['Light','Medium','Dark'].map(o=>`<option ${ui.roast===o?'selected':''}>${o}</option>`).join('')}</select></div></div><label class="field-label">Processing method</label><select class="select" data-change="guide-process">${PROCESSES.map(p=>`<option ${ui.process===p.name?'selected':''}>${html(p.name)}</option>`).join('')}</select>
 <div class="rule"></div><h3 class="section-title">${html(origin.name)} · ${html(origin.region)}</h3><p class="muted-sm">${html(origin.hints)}</p><div class="chip-row">${origin.labels.map(label=>`<span class="chip gray">${html(label)}</span>`).join('')}</div>
 <div class="section-title" style="margin-top:18px">${html(cp?.name||'Processing notes')}</div><p class="muted-sm">${html(cp?.description)}</p>
 <div class="metric-grid">${metric('15 g','Starting dose')}${metric('225 g','Starting water')}${metric(`${temp}°C`,'Test temperature')}</div><p class="field-help">Heuristic temperature for ${html(ui.roast.toLowerCase())} roast; not a scientifically established origin-specific optimum. Adjustable across your preferred 88–95°C range.</p>
 <div class="actions"><button class="btn" data-act="save-suggested-recipe">Save test recipe →</button></div></div>
 <div class="section-header"><h2 class="section-title">Explore origins</h2><span class="section-kicker">Illustrative, not predictive</span></div>${ORIGINS.map(o=>`<div class="card compact origin-item"><div class="flex between"><h3>${html(o.name)}</h3><span class="section-kicker">${html(o.region)}</span></div><p>${html(o.hints)}</p><button class="button-link" data-act="show-origin" data-value="${html(o.name)}">See starter guidance →</button></div>`).join('')}
 <div class="inline-note">To isolate a cause, adjust one variable per brew and compare the actual cup. Specialty coffee flavor is shaped by variety, growing conditions, processing, roasting and brewing together [Terroir 2022; Guinard 2023].</div>`;}
function renderTroubleshoot(){return `<div class="notice">These are <b>trial changes</b>, not scientific diagnoses. Adjust one parameter at a time; pour structure and individual coffee lots can affect the outcome.</div><div class="section-header"><h2 class="section-title">Find a better cup</h2></div>${TROUBLE.map(item=>`<div class="card compact"><h3 class="section-title">${html(item.title)}</h3><p class="muted-sm"><b>Possible cause:</b> ${html(item.why)}</p><p class="muted-sm"><b>Next experiment:</b> ${html(item.try)}</p><p class="field-help">${html(item.caution)}</p></div>`).join('')}`;}
function renderResearch(){return `<div class="notice blue"><b>Evidence labels matter.</b> Peer-reviewed findings and manufacturer specifications are separated from practical recommendations. Every paper below has an offline summary and an online link to its source.</div><div class="section-header"><h2 class="section-title">Source library</h2><span class="section-kicker">${SOURCES.length} verified references</span></div><div class="card">${SOURCES.map(s=>`<div class="research-item"><div class="ref-meta">${html(s.type)} · ${s.year}</div><h3>${html(s.title)}</h3><p class="abstract"><b>What it supports:</b> ${html(s.summary)}</p><p class="abstract"><b>Important limit:</b> ${html(s.limit)}</p><a class="reference-link" href="${html(s.url)}" target="_blank" rel="noopener noreferrer">Open original source ↗</a></div>`).join('')}</div><div class="notice warn">Scientific articles are summarized locally. Their full web pages require internet access. The app does not download copyrighted full texts.</div>`;}
function renderSettings(){return `${header('THIS DEVICE ONLY','Your private setup.','Everything you enter is stored in this iPhone’s browser storage. There are no accounts, sync or tracking.')}
 <div class="card"><h2 class="section-title">Equipment profile</h2><div class="feature"><div class="num">01</div><div><h3>Hario V60 Dripper NEO · size 02</h3><p>Default brewer. Rib geometry differs from the classic V60, so use actual taste rather than a universal time target.</p></div></div><div class="feature"><div class="num">02</div><div><h3>1Zpresso X-Ultra</h3><p>Record rotations and numbered dial position separately. Default ~3 rotations + 4.5; zero points can differ.</p></div></div><div class="feature"><div class="num">03</div><div><h3>Hanabishi gooseneck kettle</h3><p>Water-temperature field is flexible. Your preferred exploration window: 88–95°C.</p></div></div></div>
 <div class="card"><h2 class="section-title">Guided-brew controls</h2><label class="switch-row"><span><b>Audio pour cues</b><div class="muted-sm">Short tone when a scheduled stage is due</div></span><input type="checkbox" data-change="setting-sound" ${state.settings.sound?'checked':''}></label><label class="switch-row"><span><b>Request screen wake lock</b><div class="muted-sm">Works only where iOS supports it; may be released in background</div></span><input type="checkbox" data-change="setting-keepAwake" ${state.settings.keepAwake?'checked':''}></label></div>
 <div class="card"><h2 class="section-title">Backups & data ownership</h2><p class="muted-sm">Browser and Home Screen apps can have separate storage. Clearing website data, uninstalling or storage eviction can erase your entries. A JSON export is your backup; it remains under your control.</p><div class="actions"><button class="btn" data-act="export">Export JSON backup</button><button class="btn secondary" data-act="import">Import backup</button></div><input id="import-file" type="file" accept=".json,application/json" class="hidden" aria-label="Choose backup JSON"><div class="rule"></div><div class="metric-grid">${metric(state.recipes.length,'Recipes')}${metric(state.beans.length,'Beans')}${metric(state.brews.length,'Brews')}</div><p class="field-help">Storage engine: ${storageMode==='indexedDB'?'IndexedDB':'localStorage fallback'}. Files are not uploaded to an app server.</p><button class="btn danger small" data-act="reset">Reset all local data</button></div>
 <div class="card"><h2 class="section-title">Home Screen installation</h2><p class="muted-sm">Deploy this app to HTTPS (such as GitHub Pages), open the URL in Safari, tap Share → Add to Home Screen, then launch it from your Home Screen. Visit once while online to cache the app.</p><div class="offline-box">Offline mode covers recipes, journal, timer and the bundled reference summaries after the first successful installation. External article links need internet.</div></div>
 <div class="muted-sm" style="text-align:center;margin:18px">Pour Lab v1.0 · Research pack reviewed October 2026 · Offline-first</div>`;}

function showModal(title,contents){$('modal-root').innerHTML=`<div class="modal-backdrop" data-backdrop="yes"><div class="modal-sheet" role="dialog" aria-modal="true" aria-label="${html(title)}"><div class="modal-top"><h2>${html(title)}</h2><button class="icon-button" aria-label="Close dialog" data-act="close-modal">×</button></div>${contents}</div></div>`;setTimeout(()=>document.querySelector('.modal-sheet input,.modal-sheet select,.modal-sheet textarea')?.focus({preventScroll:true}),25);}
function closeModal(){$('modal-root').innerHTML='';}
function optionList(values,active){return values.map(x=>`<option value="${html(x)}" ${active===x?'selected':''}>${html(x)}</option>`).join('');}
function pourEditRow(p={at:0,water:45}){return `<div class="pour-editor-row"><div><label class="field-label">At (m:ss)</label><input class="input" data-pour-time value="${fmt(p.at)}" inputmode="numeric" placeholder="0:40" required></div><div><label class="field-label">Cumulative water (g)</label><input class="input" data-pour-water type="number" inputmode="decimal" min="1" step="0.1" value="${p.water}" required></div><button type="button" class="icon-button" data-act="remove-pour" aria-label="Remove pour">×</button></div>`;}
function recipeForm(recipe=null,beanId=null){const r=recipe||{id:'',name:'New pour-over recipe',beanId:beanId||state.beans[0]?.id,dose:15,water:225,temp:92,grindRot:3,grindDial:4.5,targetTime:165,mode:'manual',notes:'',pours:[{at:0,water:45},{at:40,water:120},{at:75,water:180},{at:110,water:225}]};if(!state.beans.length){toast('Add a coffee bean first.');beanForm();return;}
 showModal(recipe?'Edit recipe':'New recipe',`<form data-form="recipe" data-id="${html(recipe?.id||'')}"><label class="field-label">Recipe name</label><input name="name" class="input" maxlength="100" value="${html(r.name)}" required><label class="field-label">Coffee bean</label><select name="beanId" class="select">${state.beans.map(b=>`<option value="${b.id}" ${b.id===r.beanId?'selected':''}>${html(b.name)}</option>`).join('')}</select>
 <div class="form-grid"><div><label class="field-label">Dose (g)</label><input name="dose" class="input" type="number" min="1" max="100" step="0.1" inputmode="decimal" value="${r.dose}" required></div><div><label class="field-label">Total water (g)</label><input name="water" class="input" type="number" min="1" max="1500" step="0.1" inputmode="decimal" value="${r.water}" required></div><div><label class="field-label">Temperature (°C)</label><input name="temp" class="input" type="number" min="40" max="100" step="1" inputmode="numeric" value="${r.temp}" required></div><div><label class="field-label">Target finish (m:ss)</label><input name="targetTime" class="input" value="${fmt(r.targetTime)}" inputmode="numeric" placeholder="2:45" required></div><div><label class="field-label">X-Ultra rotations</label><input name="grindRot" class="input" type="number" min="0" max="4" step="1" inputmode="numeric" value="${r.grindRot}" required></div><div><label class="field-label">X-Ultra dial (0–5.9)</label><input name="grindDial" class="input" type="number" min="0" max="5.9" step="0.1" inputmode="decimal" value="${r.grindDial}" required></div></div>
 <p class="field-help">The dial notation is the one you see on the grinder. A full turn has 6 numbered units (60 clicks). This does not equal particle size in µm.</p><label class="field-label">Default timer mode</label><select name="mode" class="select">${optionList(['manual','timed'],r.mode)}</select><p class="field-help">manual = tap the next pour when the bed is visible; timed = prompts at your scheduled times.</p>
 <div class="section-header"><h2 class="section-title">Pour sequence</h2><button type="button" class="button-link" data-act="add-pour">+ Add pour</button></div><div id="pour-editor">${r.pours.map(pourEditRow).join('')}</div><p class="field-help">Use cumulative water weights. The final pour must equal total water. First pour starts at 0:00.</p>
 <label class="field-label">Method notes</label><textarea name="notes" class="textarea">${html(r.notes||'')}</textarea><div class="form-footer"><button type="button" class="btn ghost" data-act="close-modal">Cancel</button><button class="btn" type="submit">Save recipe</button></div></form>`);}
function beanForm(bean=null){const b=bean||{name:'',origin:'Colombia',region:'',variety:'Arabica',process:'Washed',roast:'Medium',roaster:'',notes:''};showModal(bean?'Edit coffee bean':'New coffee bean',`<form data-form="bean" data-id="${html(bean?.id||'')}"><label class="field-label">Coffee / lot name</label><input name="name" class="input" maxlength="120" value="${html(b.name)}" placeholder="Colombia · Farm / coffee name" required>
 <div class="form-grid"><div><label class="field-label">Country</label><input name="origin" class="input" list="origin-list" value="${html(b.origin)}" required><datalist id="origin-list">${ORIGINS.map(o=>`<option value="${html(o.name)}"></option>`).join('')}</datalist></div><div><label class="field-label">Region / farm</label><input name="region" class="input" value="${html(b.region||'')}"></div><div><label class="field-label">Variety / species</label><input name="variety" class="input" value="${html(b.variety||'')}"></div><div><label class="field-label">Roast level</label><select name="roast" class="select">${optionList(['Light','Medium-light','Medium','Medium-dark','Dark','Unknown'],b.roast)}</select></div></div><label class="field-label">Processing</label><input name="process" class="input" list="process-list" value="${html(b.process)}" required><datalist id="process-list">${PROCESSES.map(p=>`<option value="${html(p.name)}"></option>`).join('')}</datalist><label class="field-label">Roaster</label><input name="roaster" class="input" value="${html(b.roaster||'')}"><label class="field-label">Bean notes</label><textarea name="notes" class="textarea">${html(b.notes||'')}</textarea><div class="form-footer"><button type="button" class="btn ghost" data-act="close-modal">Cancel</button><button class="btn" type="submit">Save coffee bean</button></div></form>`);}
function showLog(brewId,firstTime=false){const b=state.brews.find(x=>x.id===brewId);if(!b)return;const r=b.recipeSnapshot||{};const s=b.senses||{};showModal(firstTime?'How did it taste?':'Brew notes',`<form data-form="brew" data-id="${html(b.id)}"><p class="muted-sm" style="margin:4px 0 12px">${html(b.beanName)} · ${html(r.name)} · ${fmt(b.actualTime)} · ${formatDate(b.date)}</p><div class="metric-grid">${metric(`${r.dose}g`,'Dose')}${metric(`${r.temp}°C`,'Water')}${metric(fmt(b.actualTime),'Brew time')}</div><label class="field-label">Overall rating (1–10)</label><div class="stars" id="rating-buttons">${[2,4,6,8,10].map(x=>`<button type="button" data-act="set-rating" data-value="${x}" class="${x===(b.rating||0)?'active':''}">${x}</button>`).join('')}</div><input type="hidden" id="brew-rating" name="rating" value="${b.rating||0}"><p class="field-help">Use 2, 4, 6, 8 or 10 for fast rating. A rating is optional.</p>
 ${['sweetness','acidity','body','clarity','bitterness'].map(key=>`<div class="slider-row"><label for="sense-${key}">${key[0].toUpperCase()+key.slice(1)}</label><input id="sense-${key}" type="range" data-sense="${key}" min="0" max="5" step="1" name="${key}" value="${s[key]??3}"><b id="val-${key}">${s[key]??3}/5</b></div>`).join('')}
 <label class="field-label">Tasting notes</label><textarea name="notes" class="textarea" placeholder="Sweet melon, citrus, floral, juicy finish …">${html(b.notes||'')}</textarea><label class="field-label">What to change next time?</label><textarea name="next" class="textarea" placeholder="Try one click coarser / fewer pours…">${html(b.next||'')}</textarea><div class="form-footer"><button type="button" class="btn ghost" data-act="close-modal">${firstTime?'Skip notes':'Cancel'}</button><button class="btn" type="submit">Save tasting log</button></div></form>`);}
function showBrewDetails(id){const b=state.brews.find(x=>x.id===id);if(!b)return;const r=b.recipeSnapshot;showModal('Brew details',`<div class="muted-sm">${formatDate(b.date)} · ${html(b.beanName)} · ${html(r.name)}</div><div class="metric-grid">${metric(fmt(b.actualTime),'Actual finish')}${metric(`${r.temp}°C`,'Temperature')}${metric(`${b.rating||'—'}/10`,'Your score')}</div><h3 class="section-title">Recorded pours</h3><table class="data-table"><thead><tr><th>Stage</th><th>Planned</th><th>Actual</th><th>Water</th></tr></thead><tbody>${b.events.map((x,i)=>`<tr><td>${stageLabel(i)}</td><td>${fmt(r.pours[i]?.at)}</td><td>${fmt(x.actualAt)}</td><td>${x.water} g</td></tr>`).join('')}</tbody></table><div class="rule"></div><p class="muted-sm"><b>Tasting:</b> ${html(b.notes||'No notes yet.')}</p><p class="muted-sm"><b>Next test:</b> ${html(b.next||'Not set.')}</p><div class="actions"><button class="btn" data-act="edit-brew-log" data-id="${b.id}">Edit tasting notes</button><button class="btn danger" data-act="delete-brew" data-id="${b.id}">Delete brew</button></div>`);}
function elapsedMs(){const r=ui.runner;if(!r)return 0;return r.paused?r.heldMs:Date.now()-r.startedAt;}
function playCue(){if(!state.settings.sound)return;try{if(!ui.audio){const Context=window.AudioContext||window.webkitAudioContext;if(Context)ui.audio=new Context();}if(!ui.audio)return;ui.audio.resume();const t=ui.audio.currentTime,o=ui.audio.createOscillator(),g=ui.audio.createGain();o.type='sine';o.frequency.setValueAtTime(880,t);o.frequency.setValueAtTime(1050,t+.08);g.gain.setValueAtTime(.055,t);g.gain.exponentialRampToValueAtTime(.001,t+.22);o.connect(g);g.connect(ui.audio.destination);o.start(t);o.stop(t+.23);}catch(e){console.info('Sound not available',e);}}
async function requestWake(){if(!state.settings.keepAwake||!('wakeLock' in navigator))return;try{if(!ui.runner?.wakeLock){const lock=await navigator.wakeLock.request('screen');if(ui.runner)ui.runner.wakeLock=lock;else lock.release();}}catch(e){console.info('Wake lock unavailable on this device',e);}}
function stopTimer(){if(ui.timerHandle)clearInterval(ui.timerHandle);ui.timerHandle=null;if(ui.runner?.wakeLock){try{ui.runner.wakeLock.release();}catch(e){}}ui.runner=null;$('timer-overlay-root')?.remove();}
function startBrew(recipe){if(!recipe)return;try{const Context=window.AudioContext||window.webkitAudioContext;if(Context&&!ui.audio){ui.audio=new Context();ui.audio.resume();}}catch(e){}ui.runner={recipe:structuredClone(recipe),startedAt:Date.now(),paused:false,heldMs:0,stageIndex:0,events:[],mode:recipe.mode||'manual',alertedStage:-1,wakeLock:null};ui.timerHandle=setInterval(tickTimer,250);requestWake();renderTimer();tickTimer();}
function renderTimer(){const run=ui.runner;if(!run)return;const r=run.recipe;const progress=run.events.length/r.pours.length*100;let root=$('timer-overlay-root');if(!root){root=document.createElement('div');root.id='timer-overlay-root';document.body.appendChild(root);}root.innerHTML=`<div class="timer-overlay" role="dialog" aria-modal="true" aria-label="Guided brewing timer"><div class="timer-header"><div><div class="card-kicker">LIVE BREW SESSION</div><div class="timer-title">${html(r.name)}</div><div class="muted-sm">${html(recipeName(r))}</div></div><button class="btn ghost small" data-act="cancel-timer">✕ End</button></div>
 <div class="flex between" style="margin-top:17px"><span class="chip">${r.dose}g / ${r.water}g</span><span class="chip gold">${r.temp}°C</span><span class="chip">${r.grindRot}r + ${r.grindDial}</span></div>
 <div class="timer-big" data-timer-value>0:00</div><div class="timer-info">Target finish ${fmt(r.targetTime)} · Actual time is always recorded</div>
 <div class="timer-ring" data-timer-ring style="--progress:${progress}"><div class="timer-ring-inner"><div class="timer-state" data-timer-stage>${run.stageIndex>=r.pours.length?'DRAINING':stageLabel(run.stageIndex)}</div><div class="timer-water" data-timer-water>${run.stageIndex>=r.pours.length?r.water:r.pours[run.stageIndex].water}<span style="font-size:20px">g</span></div><div class="timer-info" data-timer-add>${run.stageIndex>=r.pours.length?'Final pour complete':`+ ${round(r.pours[run.stageIndex].water-(r.pours[run.stageIndex-1]?.water||0))} g this pour`}</div></div></div>
 <div class="segment"><button class="${run.mode==='manual'?'on':''}" data-act="timer-mode" data-value="manual">Bed visible</button><button class="${run.mode==='timed'?'on':''}" data-act="timer-mode" data-value="timed">Timed cues</button></div>
 <div class="timer-stage"><h3 data-timer-status></h3><p data-timer-details></p></div>
 <div class="timer-progress">${r.pours.map((p,i)=>`<span class="${i<run.stageIndex?'done':i===run.stageIndex?'current':''}"></span>`).join('')}</div>
 <div class="timer-bottom"><div class="timer-controls"><button class="btn secondary" data-act="pause-timer">${run.paused?'Resume':'Pause'}</button>${run.stageIndex>=r.pours.length?'<button class="btn" data-act="finish-brew">Finish & log →</button>':`<button class="btn" data-act="mark-pour" ${run.paused?'disabled':''}>Mark ${r.pours[run.stageIndex].water}g poured ✓</button>`}</div><p class="timer-info">${run.mode==='manual'?'When the bed is visible, pour to the displayed cumulative water weight and tap “Mark poured.”':'A cue sounds when the scheduled time arrives. Tap “Mark poured” to log the actual moment.'}</p></div></div>`;}
function tickTimer(){const run=ui.runner;if(!run)return;const r=run.recipe;const secs=Math.floor(elapsedMs()/1000),p=r.pours[run.stageIndex];const done=run.stageIndex>=r.pours.length;
 const timer=$('timer-overlay-root');if(!timer)return;
 const value=timer.querySelector('[data-timer-value]');if(value)value.textContent=fmt(secs);
 const ring=timer.querySelector('[data-timer-ring]');if(ring)ring.style.setProperty('--progress',String(Math.min(100,secs/Math.max(1,r.targetTime)*100)));
 const status=timer.querySelector('[data-timer-status]'),details=timer.querySelector('[data-timer-details]');
 if(!status||!details)return;
 if(run.paused){status.textContent='Timer paused';details.textContent='Resume when you are ready. Your elapsed time is preserved.';return;}
 if(done){status.textContent='Let the dripper finish';details.textContent=`Final water target reached. Target finish ${fmt(r.targetTime)}. Tap Finish & log when the drawdown is complete.`;return;}
 if(run.mode==='manual'){status.textContent=run.stageIndex===0?'Start with the bloom':`Wait for the bed to appear`;
  details.textContent=run.stageIndex===0?`Pour gently to ${p.water} g and mark when done. Suggested bloom wait: ~40 seconds.`:`Next: pour to ${p.water} g (+${round(p.water-(r.pours[run.stageIndex-1]?.water||0))} g). Suggested time ${fmt(p.at)} — your bed takes priority.`;
 }else if(secs>=p.at){status.textContent=`Time to ${stageLabel(run.stageIndex).toLowerCase()}`;details.textContent=`Scheduled ${fmt(p.at)} · Pour to ${p.water} g cumulative. Mark the pour to log its actual time.`;if(run.alertedStage!==run.stageIndex){run.alertedStage=run.stageIndex;playCue();}}
 else{status.textContent=`Next pour in ${fmt(p.at-secs)}`;details.textContent=`Scheduled at ${fmt(p.at)} · Pour to ${p.water} g cumulative.`;}
}
function markPour(){const run=ui.runner;if(!run||run.paused)return;const stage=run.recipe.pours[run.stageIndex];if(!stage)return;run.events.push({stage:run.stageIndex,actualAt:Math.floor(elapsedMs()/1000),water:stage.water});run.stageIndex++;renderTimer();tickTimer();}
async function finishBrew(){const run=ui.runner;if(!run)return;if(run.events.length===0){toast('Mark at least one pour first.');return;}const recipe=run.recipe;const currentBean=getBean(recipe.beanId);const b={id:uid(),date:new Date().toISOString(),recipeId:recipe.id,beanId:recipe.beanId,beanName:currentBean?.name||'Unknown coffee',recipeSnapshot:recipe,actualTime:Math.floor(elapsedMs()/1000),events:structuredClone(run.events),mode:run.mode,rating:0,senses:{sweetness:3,acidity:3,body:3,clarity:3,bitterness:3},notes:'',next:''};stopTimer();state.brews.push(b);ui.tab='history';await save();render();showLog(b.id,true);}
function confirmAction(msg){return window.confirm(msg);}
function handleClick(evt){if(evt.target.dataset.backdrop==='yes'){closeModal();return;}const el=evt.target.closest('[data-nav],[data-nav-to],[data-act]');if(!el)return;if(el.dataset.nav){setTab(el.dataset.nav);return;}if(el.dataset.navTo){setTab(el.dataset.navTo);return;}const id=el.dataset.id,val=el.dataset.value;switch(el.dataset.act){
 case 'add-recipe':recipeForm();break;case 'add-bean':beanForm();break;
 case 'edit-recipe':recipeForm(getRecipe(id));break;case 'edit-bean':beanForm(getBean(id));break;
 case 'create-recipe-for-bean':recipeForm(null,id);break;
 case 'switch-recipe-tab':ui.recipeTab=val;render();break;
 case 'switch-learn-tab':ui.learnTab=val;render();break;
 case 'show-origin':ui.origin=val;ui.learnTab='guide';render();window.scrollTo({top:0,behavior:'instant'});break;
 case 'close-modal':closeModal();break;
 case 'add-pour':{const ed=$('pour-editor');const rows=[...ed.querySelectorAll('.pour-editor-row')];const last=rows[rows.length-1];const prevTime=last?parseTime(last.querySelector('[data-pour-time]').value):0;const prevWater=last?n(last.querySelector('[data-pour-water]').value):0;ed.insertAdjacentHTML('beforeend',pourEditRow({at:prevTime+30,water:prevWater+45}));break;}
 case 'remove-pour':{const ed=$('pour-editor');if(ed.querySelectorAll('.pour-editor-row').length===1){toast('A recipe needs at least one pour.');return;}el.closest('.pour-editor-row')?.remove();break;}
 case 'use-recipe':ui.selectedRecipeId=id;state.settings.selectedRecipeId=id;save();setTab('brew');toast('Recipe selected');break;
 case 'duplicate-recipe':{const r=getRecipe(id);if(!r)return;const now=new Date().toISOString();const copy=structuredClone(r);copy.id=uid();copy.name=`${r.name} · Copy`;copy.createdAt=now;copy.updatedAt=now;state.recipes.push(copy);persistAndRender('Recipe duplicated');break;}
 case 'delete-recipe':{const r=getRecipe(id);if(!r||!confirmAction(`Delete “${r.name}”? Past brew logs will keep a snapshot.`))return;state.recipes=state.recipes.filter(x=>x.id!==id);if(ui.selectedRecipeId===id)ui.selectedRecipeId=state.recipes[0]?.id||null;state.settings.selectedRecipeId=ui.selectedRecipeId;persistAndRender('Recipe deleted');break;}
 case 'delete-bean':{const b=getBean(id);if(!b)return;if(state.recipes.some(x=>x.beanId===id)||state.brews.some(x=>x.beanId===id)){toast('This bean is referenced by recipes or brews. Delete those first.');return;}if(!confirmAction(`Delete “${b.name}”?`))return;state.beans=state.beans.filter(x=>x.id!==id);persistAndRender('Coffee bean deleted');break;}
 case 'start-brew':startBrew(selectedRecipe());break;
 case 'timer-mode':if(ui.runner){ui.runner.mode=val;ui.runner.alertedStage=-1;renderTimer();tickTimer();}break;
 case 'pause-timer':if(ui.runner){const r=ui.runner;if(!r.paused){r.heldMs=elapsedMs();r.paused=true;}else{r.startedAt=Date.now()-r.heldMs;r.paused=false;}renderTimer();tickTimer();}break;
 case 'mark-pour':markPour();break;
 case 'finish-brew':finishBrew();break;
 case 'cancel-timer':if(confirmAction('End without saving this brew?'))stopTimer();break;
 case 'edit-brew-log':closeModal();showLog(id);break;
 case 'view-brew':showBrewDetails(id);break;
 case 'delete-brew':if(confirmAction('Permanently delete this brew log?')){state.brews=state.brews.filter(x=>x.id!==id);closeModal();persistAndRender('Brew deleted');}break;
 case 'repeat-brew':{const b=state.brews.find(x=>x.id===id);if(!b)return;const r=getRecipe(b.recipeId);if(r){ui.selectedRecipeId=r.id;state.settings.selectedRecipeId=r.id;save();setTab('brew');toast('Recipe selected for another brew');}else{const snap=structuredClone(b.recipeSnapshot);snap.id=uid();snap.name+=` · Restored`;state.recipes.push(snap);ui.selectedRecipeId=snap.id;persistAndRender('Past recipe restored');setTab('brew');}break;}
 case 'set-rating':{const rating=$('brew-rating');if(!rating)return;rating.value=val;document.querySelectorAll('#rating-buttons button').forEach(b=>b.classList.toggle('active',b.dataset.value===val));break;}
 case 'save-suggested-recipe':{const origin=ui.origin,proc=ui.process,roast=ui.roast;let bean=state.beans.find(b=>b.origin===origin&&b.process===proc&&b.roast===roast);if(!bean){bean={id:uid(),name:`${origin} · ${proc}`,origin,region:'',variety:'',roast,process:proc,roaster:'',notes:'Created from an experimental origin guide. Update with bag-specific details.',createdAt:new Date().toISOString()};state.beans.push(bean);}const copy=structuredClone(state.recipes[0]||defaultState().recipes[0]);copy.id=uid();copy.beanId=bean.id;copy.name=`${origin} · ${proc} test`;copy.temp=roast==='Light'?94:roast==='Dark'?89:92;copy.grindRot=3;copy.grindDial=4.5;copy.mode='manual';copy.notes='Experimental starting point. Country alone does not determine ideal brewing parameters.';copy.createdAt=new Date().toISOString();copy.updatedAt=copy.createdAt;state.recipes.push(copy);ui.selectedRecipeId=copy.id;ui.recipeTab='recipes';ui.tab='recipes';persistAndRender('Experimental recipe saved');break;}
 case 'export':exportBackup();break;case 'import':$('import-file')?.click();break;
 case 'reset':if(confirmAction('Erase ALL local recipes, coffee beans, and brew logs? Export a backup first.')){if(confirmAction('Confirm permanent reset of all Pour Lab data on this device.')){state=defaultState();ui.selectedRecipeId=state.settings.selectedRecipeId;persistAndRender('Local notebook reset');}}break;
 default:break;}}
async function handleSubmit(evt){const form=evt.target.closest('form[data-form]');if(!form)return;evt.preventDefault();const f=new FormData(form);if(form.dataset.form==='bean'){
 const bean={id:form.dataset.id||uid(),name:String(f.get('name')).trim(),origin:String(f.get('origin')).trim(),region:String(f.get('region')).trim(),variety:String(f.get('variety')).trim(),roast:String(f.get('roast')),process:String(f.get('process')).trim(),roaster:String(f.get('roaster')).trim(),notes:String(f.get('notes')).trim(),createdAt:new Date().toISOString()};if(!bean.name||!bean.origin||!bean.process){toast('Name, origin and process are required.');return;}const pos=state.beans.findIndex(x=>x.id===bean.id);if(pos>=0){bean.createdAt=state.beans[pos].createdAt;state.beans[pos]=bean;}else state.beans.push(bean);closeModal();await persistAndRender('Coffee bean saved');return;
 }
 if(form.dataset.form==='recipe'){
 const pours=[...form.querySelectorAll('.pour-editor-row')].map(row=>({at:parseTime(row.querySelector('[data-pour-time]').value),water:n(row.querySelector('[data-pour-water]').value,NaN)}));const duration=parseTime(f.get('targetTime'));const dose=n(f.get('dose')),water=n(f.get('water')),temp=n(f.get('temp')),grindRot=n(f.get('grindRot')),grindDial=n(f.get('grindDial'));if(!Number.isFinite(duration)||duration<1||pours.some(p=>!Number.isFinite(p.at)||!Number.isFinite(p.water))){toast('Check the times. Use m:ss (e.g., 1:15).');return;}if(dose<=0||water<=0||temp<40||temp>100||grindRot<0||grindRot>4||grindDial<0||grindDial>=6||grindRot+grindDial/6>4.5){toast('Check dose, water, temperature and X-Ultra range (maximum 4.5 turns).');return;}if(!pours.length||pours[0].at!==0||pours.some((p,i)=>i>0&&(p.at<=pours[i-1].at||p.water<=pours[i-1].water))||Math.abs(pours[pours.length-1].water-water)>.11){toast('Pours must increase in time and water, start at 0:00, and end at total water.');return;}if(duration<=pours[pours.length-1].at){toast('Finish target should come after your last pour.');return;}
 const now=new Date().toISOString();const recipe={id:form.dataset.id||uid(),beanId:String(f.get('beanId')),name:String(f.get('name')).trim(),dose,water,temp,grindRot,grindDial,targetTime:duration,mode:String(f.get('mode')),pours,notes:String(f.get('notes')).trim(),createdAt:now,updatedAt:now};if(!recipe.name||!getBean(recipe.beanId)){toast('Select a valid coffee bean and name.');return;}
 const pos=state.recipes.findIndex(x=>x.id===recipe.id);if(pos>=0){recipe.createdAt=state.recipes[pos].createdAt;state.recipes[pos]=recipe;}else state.recipes.push(recipe);ui.selectedRecipeId=recipe.id;state.settings.selectedRecipeId=recipe.id;closeModal();await persistAndRender('Recipe saved');return;
 }
 if(form.dataset.form==='brew'){const b=state.brews.find(x=>x.id===form.dataset.id);if(!b)return;b.rating=clamp(n(f.get('rating')),0,10);b.senses=Object.fromEntries(['sweetness','acidity','body','clarity','bitterness'].map(k=>[k,clamp(n(f.get(k)),0,5)]));b.notes=String(f.get('notes')).trim();b.next=String(f.get('next')).trim();closeModal();await persistAndRender('Tasting notes saved');return;}}
function handleChange(evt){const t=evt.target;const change=t.dataset.change;if(change){const value=t.type==='checkbox'?t.checked:t.value;switch(change){case 'select-recipe':ui.selectedRecipeId=value;state.settings.selectedRecipeId=value;save();render();break;case 'filter-history':ui.historyBeanId=value;render();break;case 'compare-a':ui.compareA=value;render();break;case 'compare-b':ui.compareB=value;render();break;case 'guide-origin':ui.origin=value;render();break;case 'guide-process':ui.process=value;render();break;case 'guide-roast':ui.roast=value;render();break;case 'setting-sound':state.settings.sound=!!value;save();break;case 'setting-keepAwake':state.settings.keepAwake=!!value;save();break;default:break;}}
 if(t.id==='import-file'&&t.files?.length)importBackup(t.files[0]);}
function handleInput(evt){const t=evt.target;if(t.dataset.sense){const value=$(`val-${t.dataset.sense}`);if(value)value.textContent=`${t.value}/5`;}}
function exportBackup(){const payload={app:'pourlab',exportedAt:new Date().toISOString(),schemaVersion:VERSION,data:state};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`pourlab-backup-${new Date().toISOString().slice(0,10)}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Backup file prepared. Save it in Files.');}
async function importBackup(file){try{if(file.size>10*1024*1024)throw new Error('File exceeds 10 MB.');const obj=JSON.parse(await file.text());if(obj?.app!=='pourlab'||obj.schemaVersion!==VERSION)throw new Error('Unrecognized Pour Lab backup or unsupported version.');const d=obj.data;if(!d||!Array.isArray(d.beans)||!Array.isArray(d.recipes)||!Array.isArray(d.brews)||!d.settings||!d.version)throw new Error('Incomplete backup file.');if(!confirmAction(`Replace this device's data with backup containing ${d.recipes.length} recipes, ${d.beans.length} beans and ${d.brews.length} brews? Current data will be overwritten.`))return;state=d;ui.selectedRecipeId=state.settings.selectedRecipeId||state.recipes[0]?.id||null;await persistAndRender('Backup imported');}catch(err){toast(`Import failed: ${err.message}`);}finally{if($('import-file'))$('import-file').value='';}}
async function init(){const stored=await readState();state=stored?.version===VERSION&&Array.isArray(stored.beans)&&Array.isArray(stored.recipes)&&Array.isArray(stored.brews)&&stored.settings?stored:defaultState();ui.selectedRecipeId=state.settings.selectedRecipeId||state.recipes[0]?.id||null;ui.process='Melon-washed (roaster label)';render();if(!stored)await save();if('serviceWorker' in navigator&&window.isSecureContext){navigator.serviceWorker.register('./sw.js').catch(e=>console.warn('Offline cache unavailable',e));}document.addEventListener('click',handleClick);document.addEventListener('submit',handleSubmit);document.addEventListener('change',handleChange);document.addEventListener('input',handleInput);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&ui.runner){tickTimer();requestWake();}});window.addEventListener('beforeunload',e=>{if(ui.runner){e.preventDefault();e.returnValue='';}});}
init().catch(e=>{$('main').innerHTML=`<div class="page"><h1>Unable to open the notebook</h1><p>${html(e.message)}</p></div>`;console.error(e);});
